alter table public.student_web_practice_questions add column concept_key text;
alter table public.ic3_arcade_questions add column concept text, add column media text, add column media_title text;
-- Null concepts retire legacy variants for future draws while preserving active turns.
alter table public.ic3_arcade_player add column settled_turn uuid, add column settled_result jsonb;
create table public.ic3_quiz_history(
 student_id uuid references public.students on delete cascade,
 concept text not null, last_seen timestamptz not null, presentations integer not null default 1, primary key(student_id,concept)
);
create table public.ic3_practice_run(
 student_id uuid not null references public.students on delete cascade, run uuid not null,
 lesson int not null, seen text[] not null default '{}', turn uuid, deadline timestamptz,
 item jsonb, result jsonb, primary key(student_id,run)
);
alter table public.ic3_quiz_history enable row level security;
alter table public.ic3_practice_run enable row level security;
revoke all on public.ic3_quiz_history, public.ic3_practice_run from public,anon,authenticated;
create function public.ic3_normalize(text) returns text immutable language sql set search_path='' as $$
 select trim(regexp_replace(lower(normalize($1,NFC)), '[^[:alnum:]]+', ' ', 'g'))
$$;

insert into public.ic3_arcade_questions(id,lesson,prompt,choices,solution,explanation,concept,media,media_title)
select id,lesson,prompt,choices,solution,explanation,concept,media,"mediaTitle" from jsonb_to_recordset($catalog$
[{"id": "1-1", "lesson": 1, "concept": "1-1", "prompt": "Máy mở nhiều ứng dụng cùng lúc thì chậm. Tài nguyên nào thường bị đầy trước khi em đóng bớt cửa sổ?", "choices": ["RAM", "Dung lượng ổ lưu trữ", "Bộ nhớ đồ họa", "Băng thông mạng"], "solution": "RAM", "explanation": "RAM giữ dữ liệu mà ứng dụng đang dùng."}
,{"id": "1-2", "lesson": 1, "concept": "1-2", "prompt": "Bài vẽ đã lưu vẫn còn sau khi tắt nguồn. Linh kiện nào có thể đang giữ tệp?", "choices": ["SSD", "RAM", "Bộ nhớ đệm CPU", "Thanh ghi CPU"], "solution": "SSD", "explanation": "SSD giữ dữ liệu khi máy mất điện."}
,{"id": "1-3", "lesson": 1, "concept": "1-3", "prompt": "Khi em tính trung bình một cột điểm, bộ phận nào thực hiện lệnh tính?", "choices": ["CPU", "RAM", "Ổ SSD", "Bộ nguồn"], "solution": "CPU", "explanation": "CPU thực hiện các lệnh xử lý."}
,{"id": "2-1", "lesson": 2, "concept": "2-1", "prompt": "Muốn đưa giọng nói vào bản trình chiếu, em cần thiết bị nào?", "choices": ["Micrô", "Loa", "Máy chiếu", "Bàn phím"], "solution": "Micrô", "explanation": "Âm thanh đi từ người nói vào máy qua micrô.", "media": "m07", "mediaTitle": "Micrô"}
,{"id": "2-2", "lesson": 2, "concept": "2-2", "prompt": "Đầu cáp trong ảnh thuộc chuẩn nào có thể mang cả hình và tiếng tới TV?", "choices": ["HDMI", "VGA", "Cáp âm thanh 3,5 mm", "Cáp DVI-D chỉ truyền hình"], "solution": "HDMI", "explanation": "HDMI mang cả tín hiệu hình ảnh và âm thanh.", "media": "m06", "mediaTitle": "Đầu cáp HDMI"}
,{"id": "2-3", "lesson": 2, "concept": "2-3", "prompt": "Thiết bị nào vừa hiển thị bản đồ vừa nhận vị trí em chạm?", "choices": ["Màn hình cảm ứng", "Máy chiếu", "Bàn rê", "Màn hình LCD không có lớp cảm ứng"], "solution": "Màn hình cảm ứng", "explanation": "Màn hình xuất hình ảnh và cảm biến nhận thao tác."}
,{"id": "3-1", "lesson": 3, "concept": "3-1", "prompt": "Em cần bàn phím vật lý tích hợp và pin để gõ bài trên tàu. Chọn thiết bị nào?", "choices": ["Laptop", "Máy bàn dạng tháp", "Màn hình rời", "Máy tính để bàn không có pin"], "solution": "Laptop", "explanation": "Laptop có pin và bàn phím trong cùng thiết bị."}
,{"id": "3-2", "lesson": 3, "concept": "3-2", "prompt": "Máy đặt cố định có linh kiện xử lý tích hợp sau màn hình. Đây là kiểu nào?", "choices": ["All-in-one", "Máy chủ dạng tủ", "Máy đọc sách", "Máy tính bàn có thùng máy rời"], "solution": "All-in-one", "explanation": "Kiểu all-in-one gộp màn hình và phần thân máy."}
,{"id": "3-3", "lesson": 3, "concept": "3-3", "prompt": "Em muốn vẽ trực tiếp lên một màn hình cảm ứng cầm tay cỡ quyển vở. Loại máy nào phù hợp nhất?", "choices": ["Máy tính bảng có hỗ trợ bút", "Máy bàn dạng tháp", "Máy bàn dùng màn hình thường", "Màn hình máy tính để bàn"], "solution": "Máy tính bảng có hỗ trợ bút", "explanation": "Máy tính bảng có thể nhận nét vẽ ngay trên màn hình khi hỗ trợ bút."}
,{"id": "4-1", "lesson": 4, "concept": "4-1", "prompt": "Để định dạng đoạn văn và tạo mục lục báo cáo, em mở ứng dụng nào?", "choices": ["Trình soạn thảo văn bản", "Trình phát nhạc", "Trình quản lý thiết bị", "Trình chỉnh sửa video"], "solution": "Trình soạn thảo văn bản", "explanation": "Trình soạn thảo hỗ trợ cấu trúc và định dạng văn bản."}
,{"id": "4-2", "lesson": 4, "concept": "4-2", "prompt": "Cả nhóm phải nhìn thấy thay đổi của nhau ngay khi gõ. Cách nào phù hợp?", "choices": ["Dùng tài liệu trực tuyến có quyền chỉnh sửa", "Gửi ảnh chụp màn hình", "Mỗi bạn in một bản", "Chia sẻ bản PDF chỉ đọc"], "solution": "Dùng tài liệu trực tuyến có quyền chỉnh sửa", "explanation": "Tài liệu dùng chung cho phép cộng tác trên cùng nội dung."}
,{"id": "4-3", "lesson": 4, "concept": "4-3", "prompt": "Danh sách vật tư thay đổi mỗi tuần. Nên dùng gì để tổng tiền tự tính lại?", "choices": ["Bảng tính có công thức", "Ảnh chụp hóa đơn", "Trình chiếu tĩnh", "Trình quản lý ảnh"], "solution": "Bảng tính có công thức", "explanation": "Công thức bảng tính cập nhật khi dữ liệu đầu vào đổi."}
,{"id": "5-1", "lesson": 5, "concept": "5-1", "prompt": "Ứng dụng gửi việc in qua thành phần nào để dùng phần cứng?", "choices": ["Hệ điều hành và trình điều khiển", "Ứng dụng quản lý phông chữ", "Trình quản lý tệp nén", "Trình quản lý bản tải xuống"], "solution": "Hệ điều hành và trình điều khiển", "explanation": "Hệ điều hành phối hợp với trình điều khiển để giao tiếp với máy in."}
,{"id": "5-2", "lesson": 5, "concept": "5-2", "prompt": "Ứng dụng chỉ hỗ trợ macOS. Trước khi cài lên laptop cần kiểm tra gì?", "choices": ["Hệ điều hành của laptop", "Màu bàn phím", "Số trang tài liệu", "Hãng sản xuất chuột"], "solution": "Hệ điều hành của laptop", "explanation": "Ứng dụng cần tương thích với hệ điều hành."}
,{"id": "5-3", "lesson": 5, "concept": "5-3", "prompt": "Trên Windows, tổ hợp nào giúp chuyển nhanh giữa các ứng dụng đang mở?", "choices": ["Alt + Tab", "Ctrl + P", "Ctrl + S", "Ctrl + Z"], "solution": "Alt + Tab", "explanation": "Alt + Tab chuyển cửa sổ đang hoạt động."}
,{"id": "6-1", "lesson": 6, "concept": "6-1", "prompt": "Em vẫn muốn giữ ứng dụng mở trên máy Windows dùng chung. Nên làm gì trước khi rời bàn?", "choices": ["Khóa máy bằng Windows + L", "Chỉ tắt màn hình", "Đổi hình nền", "Để máy ở Desktop mà không khóa"], "solution": "Khóa máy bằng Windows + L", "explanation": "Khóa phiên yêu cầu xác thực khi quay lại."}
,{"id": "6-2", "lesson": 6, "concept": "6-2", "prompt": "Để một học sinh làm bài thông thường, nên cấp loại tài khoản nào?", "choices": ["Người dùng tiêu chuẩn", "Quản trị viên toàn hệ thống", "Tài khoản dùng chung của giáo viên", "Tài khoản quản trị của phòng máy"], "solution": "Người dùng tiêu chuẩn", "explanation": "Quyền tiêu chuẩn đủ để học và hạn chế thay đổi hệ thống."}
,{"id": "6-3", "lesson": 6, "concept": "6-3", "prompt": "Hết tiết, bạn khác cần dùng máy bằng tài khoản riêng. Em chọn gì?", "choices": ["Đăng xuất", "Ẩn cửa sổ", "Tắt loa", "Chuyển sang một cửa sổ khác"], "solution": "Đăng xuất", "explanation": "Đăng xuất kết thúc phiên hiện tại."}
,{"id": "7-1", "lesson": 7, "concept": "7-1", "prompt": "Tên tệp nào dễ nhận ra lớp, nội dung và phiên bản nhất?", "choices": ["6A_BaoCaoNuoc_v02.docx", "moi.docx", "cuoicungthat.docx", "tapmoi.docx"], "solution": "6A_BaoCaoNuoc_v02.docx", "explanation": "Tên có quy ước giúp nhận diện và sắp xếp."}
,{"id": "7-2", "lesson": 7, "concept": "7-2", "prompt": "Bản sao nào còn dùng được nếu ổ trong laptop hỏng hoàn toàn?", "choices": ["Bản sao trên ổ ngoài đã tháo", "Bản trong thư mục khác cùng ổ", "Lối tắt trên Desktop", "Bản sao trong thư mục khác cùng ổ C"], "solution": "Bản sao trên ổ ngoài đã tháo", "explanation": "Bản sao độc lập vẫn còn khi thiết bị gốc hỏng."}
,{"id": "7-3", "lesson": 7, "concept": "7-3", "prompt": "Tài liệu đám mây đã tự lưu sau khi em xóa nhầm. Nên kiểm tra gì?", "choices": ["Lịch sử phiên bản", "Tên máy tính", "Độ phân giải màn hình", "Vị trí biểu tượng Desktop"], "solution": "Lịch sử phiên bản", "explanation": "Lịch sử phiên bản có thể khôi phục nội dung trước chỉnh sửa."}
,{"id": "8-1", "lesson": 8, "concept": "8-1", "prompt": "Em cần số hóa một trang giấy để lưu trên máy. Chọn thiết bị nào?", "choices": ["Máy quét", "Loa", "Máy chiếu", "Máy in laser"], "solution": "Máy quét", "explanation": "Máy quét biến nội dung giấy thành dữ liệu số.", "media": "m09", "mediaTitle": "Máy quét phẳng"}
,{"id": "8-2", "lesson": 8, "concept": "8-2", "prompt": "Nhận tệp dự án, em muốn thử sửa mà giữ bản ban đầu. Làm gì trước?", "choices": ["Tạo một bản sao có tên mới", "Đổi hình nền", "Xóa bản ban đầu", "Chỉ lưu đè lên tệp gốc"], "solution": "Tạo một bản sao có tên mới", "explanation": "Bản sao cho phép thử thay đổi mà vẫn giữ bản gốc."}
,{"id": "8-3", "lesson": 8, "concept": "8-3", "prompt": "Muốn trình chiếu lần lượt từng trang trước lớp, em dùng loại ứng dụng nào?", "choices": ["Trình tạo bài trình chiếu", "Trình nén tệp", "Trình phát âm thanh", "Trình quản lý ổ đĩa"], "solution": "Trình tạo bài trình chiếu", "explanation": "Trình chiếu tổ chức nội dung thành các slide."}
,{"id": "9-1", "lesson": 9, "concept": "9-1", "prompt": "Kết nối tai nghe gần laptop mà không cần Internet. Công nghệ nào phù hợp?", "choices": ["Bluetooth", "GPS", "HDMI", "Đầu nối VGA"], "solution": "Bluetooth", "explanation": "Bluetooth kết nối thiết bị ở khoảng cách ngắn."}
,{"id": "9-2", "lesson": 9, "concept": "9-2", "prompt": "Máy có Wi-Fi yếu sau hai bức tường. Thử thay đổi nào trước?", "choices": ["Di chuyển gần điểm truy cập", "Tăng âm lượng", "Giảm độ sáng", "Tắt màn hình laptop"], "solution": "Di chuyển gần điểm truy cập", "explanation": "Khoảng cách và vật cản ảnh hưởng tín hiệu vô tuyến."}
,{"id": "9-3", "lesson": 9, "concept": "9-3", "prompt": "Hai mạng có tên gần giống nhau. Trước khi đăng nhập, em nên làm gì?", "choices": ["Hỏi nhân viên tên mạng chính thức", "Chọn mạng có chữ FREE", "Gửi mật khẩu cho người lạ", "Chọn ngay mạng không cần mật khẩu"], "solution": "Hỏi nhân viên tên mạng chính thức", "explanation": "Xác minh tên mạng giúp tránh kết nối nhầm."}
,{"id": "10-1", "lesson": 10, "concept": "10-1", "prompt": "Laptop đang bật chế độ máy bay và Wi-Fi bị tắt. Để vào mạng lớp, em kiểm tra gì đầu tiên?", "choices": ["Bật lại Wi-Fi và chọn đúng mạng", "Thay máy in", "Xóa bài đã lưu", "Tăng độ sáng màn hình"], "solution": "Bật lại Wi-Fi và chọn đúng mạng", "explanation": "Cần kết nối vô tuyến tới mạng trước khi truy cập."}
,{"id": "10-2", "lesson": 10, "concept": "10-2", "prompt": "TV báo không có tín hiệu dù laptop đang chạy. Kiểm tra gì trước?", "choices": ["Cáp và nguồn vào HDMI trên TV", "Mực máy in", "Dung lượng thư rác", "Cài lại bàn phím"], "solution": "Cáp và nguồn vào HDMI trên TV", "explanation": "Nguồn vào cần trùng cổng đã cắm cáp."}
,{"id": "10-3", "lesson": 10, "concept": "10-3", "prompt": "Trước khi chỉnh sửa video nhóm có dung lượng lớn, nên làm gì?", "choices": ["Giữ bản nguồn ở nơi sao lưu riêng", "Chỉ đổi tên lối tắt", "Xóa toàn bộ cảnh quay", "Đưa toàn bộ bản nguồn vào thùng rác"], "solution": "Giữ bản nguồn ở nơi sao lưu riêng", "explanation": "Bản nguồn giúp dựng lại nếu bản chỉnh sửa bị hỏng."}
,{"id": "11-1", "lesson": 11, "concept": "11-1", "prompt": "Muốn mở lại đúng trang tài liệu tuần sau, em dùng chức năng nào?", "choices": ["Thêm dấu trang", "Tải lại trang", "Đóng tab", "Lịch sử tải xuống"], "solution": "Thêm dấu trang", "explanation": "Dấu trang lưu địa chỉ trang để truy cập sau."}
,{"id": "11-2", "lesson": 11, "concept": "11-2", "prompt": "Em vừa bấm một liên kết. Nút nào đưa tab về trang trước?", "choices": ["Quay lại", "Trang chủ", "Tải xuống", "Tải lại trang (Refresh)"], "solution": "Quay lại", "explanation": "Nút quay lại đi một bước trong lịch sử tab."}
,{"id": "11-3", "lesson": 11, "concept": "11-3", "prompt": "Trang lớp đổi địa chỉ. Em cần cập nhật gì trong dấu trang?", "choices": ["URL đã lưu", "Kích thước cửa sổ", "Cỡ chữ trình duyệt", "Màu giao diện trình duyệt"], "solution": "URL đã lưu", "explanation": "URL xác định đích đến của dấu trang."}
,{"id": "12-1", "lesson": 12, "concept": "12-1", "prompt": "Muốn tìm chính xác cụm “vòng tuần hoàn nước”, em đặt cụm từ trong gì?", "choices": ["Dấu ngoặc kép", "Dấu ngoặc vuông", "Hai dấu cộng", "Dấu gạch ngang"], "solution": "Dấu ngoặc kép", "explanation": "Ngoặc kép yêu cầu khớp cụm từ trong nhiều công cụ tìm kiếm."}
,{"id": "12-2", "lesson": 12, "concept": "12-2", "prompt": "Tìm “rùa” cho ra cả truyện tranh. Em muốn tài liệu về môi trường sống. Chọn truy vấn nào?", "choices": ["môi trường sống rùa biển Việt Nam", "rùa đẹp", "động vật", "hình rùa hoạt hình"], "solution": "môi trường sống rùa biển Việt Nam", "explanation": "Từ khóa cụ thể thu hẹp phạm vi theo đối tượng và chủ đề."}
,{"id": "12-3", "lesson": 12, "concept": "12-3", "prompt": "Để chọn nguồn cho bài khoa học, dấu hiệu nào đáng kiểm tra nhất?", "choices": ["Tác giả, bằng chứng và ngày cập nhật", "Trang có nhiều hiệu ứng", "Tiêu đề viết hoa", "Màu nền trang web"], "solution": "Tác giả, bằng chứng và ngày cập nhật", "explanation": "Những chi tiết này giúp đánh giá độ tin cậy và tính cập nhật."}
,{"id": "13-1", "lesson": 13, "concept": "13-1", "prompt": "Dùng ảnh CC BY trong bài thuyết trình. Em cần làm gì?", "choices": ["Ghi công tác giả và dẫn giấy phép", "Ghi tên mình làm tác giả", "Xóa mọi thông tin nguồn", "Để nguyên ảnh mà không cần ghi nguồn"], "solution": "Ghi công tác giả và dẫn giấy phép", "explanation": "Điều kiện BY yêu cầu ghi công phù hợp."}
,{"id": "13-2", "lesson": 13, "concept": "13-2", "prompt": "Ảnh mang điều kiện NC. Trước khi dùng cho quảng cáo thương mại cần làm gì?", "choices": ["Xin quyền phù hợp hoặc chọn ảnh khác", "Chỉ cần đổi màu ảnh", "Chụp màn hình là đủ", "Tự gắn tên tác giả mới"], "solution": "Xin quyền phù hợp hoặc chọn ảnh khác", "explanation": "NC giới hạn sử dụng cho mục đích phi thương mại."}
