,{"id": "ap-3-aio-space", "concept": "aio-space", "lesson": 3, "prompt": "Bàn thực hành quá hẹp để đặt cả thùng máy và màn hình riêng. Kiểu máy cố định nào giúp tiết kiệm chỗ?", "choices": ["All-in-one", "Máy bàn có thùng máy rời và hai màn hình", "Máy bàn có thêm màn hình phụ", "Máy chủ dạng tháp và màn hình rời"], "solution": "All-in-one", "explanation": "All-in-one đặt các linh kiện máy tính trong cùng cụm màn hình."}
,{"id": "ap-3-dual-input", "concept": "dual-input", "lesson": 3, "prompt": "Khi so sánh hai máy tính bảng để vẽ bằng bút, em cần kiểm tra thông số nào trước?", "choices": ["Khả năng hỗ trợ loại bút cần dùng", "Số lượng ứng dụng cài sẵn", "Màu của vỏ bảo vệ", "Dung lượng của hộp sạc tai nghe"], "solution": "Khả năng hỗ trợ loại bút cần dùng", "explanation": "Màn hình cảm ứng không bảo đảm tương thích với mọi bút điện tử."}
,{"id": "ap-4-web-access", "concept": "web-access", "lesson": 4, "prompt": "Lớp chỉ được dùng trình duyệt và có Internet. Em chọn phiên bản công cụ nào để làm báo cáo?", "choices": ["Bản chạy trực tiếp trên web", "Bộ cài cần quyền quản trị", "Bản cần cài trình điều khiển mới", "Bộ cài dành cho hệ điều hành khác"], "solution": "Bản chạy trực tiếp trên web", "explanation": "Ứng dụng web phù hợp khi không thể cài phần mềm trên máy."}
,{"id": "ap-4-poster", "concept": "poster", "lesson": 4, "prompt": "Em đã có số liệu trong bảng tính và muốn làm áp phích. Công việc nào phù hợp với ứng dụng đồ họa?", "choices": ["Sắp xếp hình, chữ và màu trên trang", "Tính tổng chi phí theo công thức", "Sắp xếp điểm từ cao xuống thấp", "Tính trung bình một cột"], "solution": "Sắp xếp hình, chữ và màu trên trang", "explanation": "Ứng dụng đồ họa giúp bố trí yếu tố thị giác cho áp phích."}
,{"id": "ap-5-print-range", "concept": "print-range", "lesson": 5, "prompt": "Với phạm vi đã nhập trong ảnh, máy in sẽ bỏ qua trang nào?", "choices": ["Trang 2", "Trang 1", "Trang 5", "Trang 7"], "solution": "Trang 2", "explanation": "Phạm vi 1, 3–5, 7 gồm các trang 1, 3, 4, 5 và 7. Trang 2 không nằm trong danh sách.", "media": "m16", "mediaTitle": "Phạm vi trang trong hộp thoại in GNOME"}
,{"id": "ap-5-window-state", "concept": "window-state", "lesson": 5, "prompt": "Em thu nhỏ cửa sổ đang soạn. Khi mở lại từ thanh tác vụ, điều gì thường xảy ra?", "choices": ["Tài liệu vẫn ở phiên đang làm", "Ứng dụng tạo tài liệu trắng mới", "Tài liệu tự chuyển thành PDF", "Hệ điều hành đăng xuất tài khoản"], "solution": "Tài liệu vẫn ở phiên đang làm", "explanation": "Thu nhỏ chỉ thay đổi cách hiển thị cửa sổ."}
,{"id": "ap-6-switch-account", "concept": "switch-account", "lesson": 6, "prompt": "Bạn cùng lớp đã khóa máy và đi lấy nước. Em cần dùng tài khoản riêng ngay. Nên chọn thao tác nào nếu máy cho phép?", "choices": ["Chuyển người dùng", "Đặt lại mật khẩu của bạn", "Tắt nguồn cưỡng bức", "Dùng tài khoản của bạn để mở khóa"], "solution": "Chuyển người dùng", "explanation": "Chuyển người dùng mở phiên riêng và giữ phiên đang khóa."}
,{"id": "ap-6-workspace", "concept": "workspace", "lesson": 6, "prompt": "Nhiều cửa sổ đang che nhau. Chế độ tổng quan trong ảnh giúp em làm việc gì?", "choices": ["Tìm và chuyển sang cửa sổ cần dùng", "Sao lưu toàn bộ tệp đang mở", "Đổi mật khẩu mọi tài khoản", "Gỡ các ứng dụng đang chạy"], "solution": "Tìm và chuyển sang cửa sổ cần dùng", "explanation": "Tổng quan hiển thị các cửa sổ để chọn mà không đóng công việc.", "media": "m18", "mediaTitle": "Tổng quan không gian làm việc GNOME"}
,{"id": "ap-7-versions", "concept": "versions", "lesson": 7, "prompt": "Hai bạn cùng nộp BaoCao.docx. Trước khi chép cả hai vào một thư mục, cần làm gì?", "choices": ["Phân biệt tên hoặc thư mục để tránh ghi đè", "Đổi cả hai sang cùng một tên ngắn", "Xóa phần mở rộng của cả hai", "Mở cả hai rồi dán đè lần lượt"], "solution": "Phân biệt tên hoặc thư mục để tránh ghi đè", "explanation": "Tên riêng hoặc thư mục riêng giúp giữ được hai bản."}
,{"id": "ap-7-folder-view", "concept": "folder-view", "lesson": 7, "prompt": "Hai tệp trong ảnh đều ghi ngày 27-08-2022. Phần nào của tên tệp cho biết tệp nào được tạo trước?", "choices": ["Giờ và phút sau ngày chụp", "Tên người đăng nhập", "Kích thước mỗi ảnh", "Tên thư mục chứa ảnh"], "solution": "Giờ và phút sau ngày chụp", "explanation": "Các tên tệp đều chứa ngày và giờ. Cùng một ngày, phần giờ và phút phân biệt hai lần chụp.", "media": "m17", "mediaTitle": "Tệp trong GNOME Files"}
,{"id": "ap-8-scan-edit", "concept": "scan-edit", "lesson": 8, "prompt": "Nhóm cần chỉnh độ sáng của bản quét và giữ một bản để đối chiếu. Trình tự nào phù hợp?", "choices": ["Quét, sao chép, chỉnh bản sao", "Chỉnh bản duy nhất rồi quét lại màn hình", "Xóa bản quét rồi mở phần mềm chỉnh ảnh", "In bản nháp rồi ghi đè bản gốc"], "solution": "Quét, sao chép, chỉnh bản sao", "explanation": "Bản sao cho phép sửa ảnh trong khi vẫn còn bản quét ban đầu."}
,{"id": "ap-8-scan-direction", "concept": "scan-direction", "lesson": 8, "prompt": "Khi quét một bức tranh trên giấy, thứ gì xuất hiện trong máy tính?", "choices": ["Ảnh số của bức tranh", "Bản in thứ hai", "Công thức bảng tính của bức tranh", "Bài trình chiếu có hiệu ứng sẵn"], "solution": "Ảnh số của bức tranh", "explanation": "Máy quét chuyển hình ảnh trên giấy thành dữ liệu số."}
,{"id": "ap-8-handoff", "concept": "handoff", "lesson": 8, "prompt": "Bạn khác mở nhầm bản áp phích nháp. Em nên thay đổi cách bàn giao nào?", "choices": ["Gửi đúng tệp cuối trong thư mục nộp riêng", "Gửi lại tất cả tệp cùng tên", "Chỉ thông báo màu nền của bản cuối", "Sửa bản gốc mà không lưu"], "solution": "Gửi đúng tệp cuối trong thư mục nộp riêng", "explanation": "Tách bản cuối giúp người nhận chọn đúng sản phẩm."}
,{"id": "ap-8-class-report", "concept": "class-report", "lesson": 8, "prompt": "Lớp đã có một cột số lượng và một cột đơn giá. Công việc nào cần bảng tính nhất?", "choices": ["Tính thành tiền cho mỗi dòng", "Quét hóa đơn giấy", "Thu âm lời giới thiệu", "Vẽ nền cho áp phích"], "solution": "Tính thành tiền cho mỗi dòng", "explanation": "Bảng tính áp dụng công thức lên dữ liệu theo từng dòng."}
,{"id": "ap-9-local-playback", "concept": "local-playback", "lesson": 9, "prompt": "Internet bị ngắt nhưng tai nghe Bluetooth vẫn phát bài nhạc đã tải. Vì sao?", "choices": ["Tệp ở trên máy và âm thanh truyền trực tiếp sang tai nghe", "Tai nghe luôn lưu mọi bài nhạc của máy", "Wi-Fi phải đang kết nối Internet", "Bài nhạc tự chuyển sang mạng di động"], "solution": "Tệp ở trên máy và âm thanh truyền trực tiếp sang tai nghe", "explanation": "Liên kết Bluetooth cục bộ hoạt động độc lập với đường Internet."}
,{"id": "ap-9-isolate-network", "concept": "isolate-network", "lesson": 9, "prompt": "Một máy không vào mạng lớp, các máy bên cạnh vẫn truy cập được. Nên kiểm tra ở đâu trước?", "choices": ["Cài đặt kết nối của máy gặp lỗi", "Tất cả tài khoản của cả trường", "Dây nguồn của mọi máy đang truy cập", "Máy chủ của mọi website"], "solution": "Cài đặt kết nối của máy gặp lỗi", "explanation": "So sánh với các máy hoạt động giúp thu hẹp phạm vi sự cố."}
,{"id": "ap-10-change-one", "concept": "change-one", "lesson": 10, "prompt": "Khi thử sửa lỗi trình chiếu, vì sao nên thay từng yếu tố một?", "choices": ["Để xác định thay đổi nào ảnh hưởng kết quả", "Để độ sáng tự tăng", "Để máy tự sao lưu mỗi lần thử", "Để không cần xem kết quả"], "solution": "Để xác định thay đổi nào ảnh hưởng kết quả", "explanation": "Thử từng biến giúp tìm nguyên nhân qua việc so sánh trước và sau."}
,{"id": "ap-10-verify-sound", "concept": "verify-sound", "lesson": 10, "prompt": "Hình trình chiếu đã hiện đúng trên TV. Cách kiểm tra đường tiếng trước tiết học là gì?", "choices": ["Phát một đoạn có âm thanh rồi nghe tại TV", "Chỉ xem ảnh bìa bài giảng", "Đổi tên tệp trình chiếu", "Chụp lại màn hình laptop"], "solution": "Phát một đoạn có âm thanh rồi nghe tại TV", "explanation": "Có hình chưa xác nhận âm thanh được đưa đến đúng thiết bị."}
,{"id": "ap-10-backup-offline", "concept": "backup-offline", "lesson": 10, "prompt": "Sắp thuyết trình ở phòng có Wi-Fi chập chờn. Cần chuẩn bị gì để vẫn mở được bài?", "choices": ["Bản đã tải về và mở thử trên máy", "Chỉ một dấu trang tới tài liệu", "Chỉ địa chỉ email của người gửi", "Chỉ một ảnh tên tệp trên Drive"], "solution": "Bản đã tải về và mở thử trên máy", "explanation": "Tệp cục bộ đã mở thử giảm phụ thuộc vào kết nối."}
,{"id": "ap-10-signal-order", "concept": "signal-order", "lesson": 10, "prompt": "Em phát video từ laptop lên TV qua cáp. Đường đi của tín hiệu hình là gì?", "choices": ["Laptop → cáp → đầu vào TV", "TV → cáp → micrô", "Tai nghe → TV → laptop", "Cáp → bàn phím → TV"], "solution": "Laptop → cáp → đầu vào TV", "explanation": "Laptop là nguồn phát, cáp truyền tín hiệu đến đầu vào của TV."}
,{"id": "ap-11-organize-marks", "concept": "organize-marks", "lesson": 11, "prompt": "Hai dấu trang cùng có tên “Tài liệu”. Làm sao để chọn đúng bài ngay trong danh sách?", "choices": ["Đổi tên dấu trang theo nội dung", "Xóa lịch sử tải xuống", "Tăng cỡ chữ trang web", "Đổi tên trình duyệt"], "solution": "Đổi tên dấu trang theo nội dung", "explanation": "Tên mô tả giúp phân biệt liên kết đã lưu mà không đổi trang đích."}
,{"id": "ap-11-tabs", "concept": "tabs", "lesson": 11, "prompt": "Em muốn giữ nguyên đề bài khi mở trang tham khảo. Nên mở liên kết bằng cách nào?", "choices": ["Trong tab mới", "Thay địa chỉ của tab đề bài", "Đóng tab đề bài trước", "Đặt trang tham khảo làm trang chủ"], "solution": "Trong tab mới", "explanation": "Tab mới cho phép chuyển qua lại giữa hai trang đang mở."}
,{"id": "ap-12-date-filter", "concept": "date-filter", "lesson": 12, "prompt": "Bài tập yêu cầu tin trong tuần qua. Thiết lập nào giảm các kết quả quá cũ?", "choices": ["Bộ lọc thời gian", "Bộ lọc màu hình ảnh", "Phóng to trang kết quả", "Đổi thư mục tải xuống"], "solution": "Bộ lọc thời gian", "explanation": "Lọc theo thời gian thu hẹp tập kết quả theo yêu cầu."}
,{"id": "ap-12-remove-filter", "concept": "remove-filter", "lesson": 12, "prompt": "Sau khi dùng nhiều bộ lọc, em không thấy kết quả nào. Thử gì trước?", "choices": ["Gỡ một điều kiện ít quan trọng rồi tìm lại", "Thêm nhiều điều kiện hơn", "Lưu trang trống vào dấu trang", "Chỉ tăng độ phân giải màn hình"], "solution": "Gỡ một điều kiện ít quan trọng rồi tìm lại", "explanation": "Nới một điều kiện có thể tìm lại kết quả liên quan."}
,{"id": "ap-13-share-alike", "concept": "share-alike", "lesson": 13, "prompt": "Em chia sẻ bản chỉnh sửa của ảnh CC BY-SA và đã ghi công. Còn cần kiểm tra gì?", "choices": ["Giấy phép của bản chuyển thể có đáp ứng điều kiện SA", "Ảnh có đúng kích thước màn hình nhà em", "Tệp đã đổi tên tác giả thành tên em", "Ảnh có được in thử trước khi đăng"], "solution": "Giấy phép của bản chuyển thể có đáp ứng điều kiện SA", "explanation": "SA yêu cầu chia sẻ bản chuyển thể theo điều kiện giấy phép tương thích."}
,{"id": "ap-13-trace-source", "concept": "trace-source", "lesson": 13, "prompt": "Bạn gửi ảnh qua nhóm chat nhưng không kèm nguồn. Bước nào giúp xác định quyền sử dụng?", "choices": ["Tìm trang gốc và đọc điều kiện của tác giả", "Dùng số lượt thích để suy ra quyền", "Đổi đuôi ảnh thành PNG", "Ghi tên nhóm chat làm chủ sở hữu"], "solution": "Tìm trang gốc và đọc điều kiện của tác giả", "explanation": "Trang gốc giúp kiểm tra tác giả và quyền sử dụng thật sự."}
,{"id": "ap-14-audience", "concept": "audience", "lesson": 14, "prompt": "Một bài đăng lớp học chỉ dành cho thành viên nhóm. Cần kiểm tra gì ngay trước khi gửi?", "choices": ["Đối tượng được xem bài", "Phông chữ mặc định", "Loại cáp mạng", "Màu của nút đăng"], "solution": "Đối tượng được xem bài", "explanation": "Phạm vi chia sẻ quyết định ai có thể xem ngay sau khi đăng."}
,{"id": "ap-14-background", "concept": "background", "lesson": 14, "prompt": "Ảnh không có mặt người nhưng phía sau có biển số nhà. Em nên xử lý thế nào trước khi đăng công khai?", "choices": ["Cắt hoặc che phần tiết lộ địa chỉ", "Chỉ đổi tên tệp", "Chỉ giảm âm lượng", "Thêm tên đường vào mô tả"], "solution": "Cắt hoặc che phần tiết lộ địa chỉ", "explanation": "Bối cảnh ảnh có thể tiết lộ vị trí kể cả khi không thấy khuôn mặt."}
,{"id": "ap-15-consent-revoke", "concept": "consent-revoke", "lesson": 15, "prompt": "Bạn đã đồng ý đăng ảnh nhưng sau đó nhờ gỡ. Phản ứng nào tôn trọng bạn?", "choices": ["Gỡ ảnh trong phạm vi mình quản lý và trao đổi lại", "Đăng thêm bản khác để hỏi ý kiến lớp", "Công khai tin nhắn xin gỡ", "Đổi chú thích rồi tiếp tục chia sẻ"], "solution": "Gỡ ảnh trong phạm vi mình quản lý và trao đổi lại", "explanation": "Tôn trọng mong muốn mới giúp bảo vệ bạn khi chia sẻ nội dung."}
,{"id": "ap-15-avoid-amplify", "concept": "avoid-amplify", "lesson": 15, "prompt": "Bạn muốn giúp báo một bình luận xúc phạm. Gửi bằng chứng ở đâu phù hợp nhất?", "choices": ["Kênh riêng cho giáo viên hoặc quản trị viên", "Trang công khai của lớp", "Bình luận bên dưới nhiều bài khác", "Nhóm trò chuyện toàn trường"], "solution": "Kênh riêng cho giáo viên hoặc quản trị viên", "explanation": "Gửi riêng cho người xử lý tránh phát tán thêm nội dung gây hại."}
,{"id": "ap-16-thread", "concept": "thread", "lesson": 16, "prompt": "Đã có một luồng hỏi đáp đúng chủ đề trên diễn đàn. Đăng câu hỏi bổ sung ở đâu dễ theo dõi nhất?", "choices": ["Trong luồng hiện có", "Trong chữ ký tài khoản", "Ở nhiều chủ đề không liên quan", "Trong phần mô tả ảnh đại diện"], "solution": "Trong luồng hiện có", "explanation": "Các trả lời cùng luồng giữ được bối cảnh thảo luận."}
,{"id": "ap-17-role-limits", "concept": "role-limits", "lesson": 17, "prompt": "Em đọc được tài liệu nhưng nút sửa bị khóa. Điều này thường cho biết gì?", "choices": ["Tài khoản có quyền xem và có thể thiếu quyền sửa", "Tài liệu chắc chắn đã bị xóa", "Tất cả thành viên đều là quản trị viên", "Không ai có thể đọc tài liệu nữa"], "solution": "Tài khoản có quyền xem và có thể thiếu quyền sửa", "explanation": "Quyền xem và quyền chỉnh sửa là hai quyền khác nhau."}
,{"id": "ap-17-policy-unclear", "concept": "policy-unclear", "lesson": 17, "prompt": "Nội quy chưa nói rõ có thể đăng đường dẫn quảng cáo hay không. Em nên làm gì?", "choices": ["Hỏi quản trị viên trước khi đăng", "Đăng thử nhiều lần", "Dùng tài khoản của bạn để đăng", "Chèn đường dẫn vào mọi bình luận"], "solution": "Hỏi quản trị viên trước khi đăng", "explanation": "Người quản trị có thể làm rõ phạm vi sử dụng diễn đàn."}
,{"id": "ap-18-attachment", "concept": "attachment", "lesson": 18, "prompt": "Thư viết “Em gửi kèm bài tập”. Bước cuối nào giúp giáo viên nhận đúng bài?", "choices": ["Đối chiếu người nhận và mở kiểm tra tệp đính kèm", "Đổi màu tất cả chữ", "Thêm nhiều địa chỉ vào Cc", "Chỉ gửi tiêu đề"], "solution": "Đối chiếu người nhận và mở kiểm tra tệp đính kèm", "explanation": "Đúng địa chỉ và đúng tệp đều cần thiết để bàn giao bài."}
,{"id": "ap-19-second-factor", "concept": "second-factor", "lesson": 19, "prompt": "Người khác đã biết mật khẩu. Yếu tố nào có thể vẫn chặn họ đăng nhập?", "choices": ["Bước xác thực bổ sung trên thiết bị của chủ tài khoản", "Đổi hình đại diện", "Đổi màu màn hình đăng nhập", "Ghi tên lớp trong hồ sơ"], "solution": "Bước xác thực bổ sung trên thiết bị của chủ tài khoản", "explanation": "Một yếu tố xác thực độc lập bổ sung lớp bảo vệ sau mật khẩu."}
,{"id": "ap-19-post-logout", "concept": "post-logout", "lesson": 19, "prompt": "Đã đăng xuất cổng nộp bài trên máy thư viện. Còn cần kiểm tra gì?", "choices": ["Tệp riêng đã tải về thư mục dùng chung", "Ảnh nền có đúng chủ đề", "Số lượng dấu trang mặc định", "Độ phân giải của màn hình"], "solution": "Tệp riêng đã tải về thư mục dùng chung", "explanation": "Đăng xuất kết thúc phiên web nhưng tệp đã tải có thể vẫn ở máy."}
,{"id": "ap-20-suspicious-install", "concept": "suspicious-install", "lesson": 20, "prompt": "Sau khi chạy tệp lạ, máy lớp liên tục mở cửa sổ bất thường. Em nên làm gì?", "choices": ["Dừng thao tác và báo người phụ trách máy", "Tiếp tục chạy tệp để thử nhiều lần", "Chép tệp sang máy bạn để so sánh", "Nhập tài khoản cá nhân để kiểm tra"], "solution": "Dừng thao tác và báo người phụ trách máy", "explanation": "Dừng sử dụng và báo sự cố giúp tránh mở rộng ảnh hưởng."}
,{"id": "ap-21-restore-location", "concept": "restore-location", "lesson": 21, "prompt": "Khi thử phục hồi một bản sao lưu, vì sao chọn thư mục khác bản đang dùng?", "choices": ["Để tránh ghi đè bản làm việc", "Để tự tăng dung lượng ổ đĩa", "Để đổi định dạng tất cả tài liệu", "Để tắt lịch sử phiên bản"], "solution": "Để tránh ghi đè bản làm việc", "explanation": "Phục hồi riêng bảo toàn bản làm việc trong khi kiểm tra bản sao."}
,{"id": "ap-21-review-rights", "concept": "review-rights", "lesson": 21, "prompt": "Một ứng dụng cũ vẫn có quyền dùng micrô dù em chỉ đọc tài liệu. Em có thể làm gì?", "choices": ["Xem lại và thu hồi quyền không còn cần", "Cấp thêm quyền camera", "Đổi tên biểu tượng ứng dụng", "Tăng âm lượng loa"], "solution": "Xem lại và thu hồi quyền không còn cần", "explanation": "Quyền truy cập nên phù hợp với chức năng đang dùng."}
,{"id": "ap-22-photo-metadata", "concept": "photo-metadata", "lesson": 22, "prompt": "Em đã đổi tên ảnh nhưng muốn kiểm tra ảnh có lưu tọa độ không. Xem ở đâu?", "choices": ["Thông tin chi tiết của tệp ảnh", "Tên thư mục chứa ảnh", "Kích thước cửa sổ hiển thị", "Màu khung ảnh trên màn hình"], "solution": "Thông tin chi tiết của tệp ảnh", "explanation": "Tọa độ có thể nằm trong siêu dữ liệu và không phụ thuộc tên tệp."}
,{"id": "ap-1-ram-locate", "concept": "ram-locate", "lesson": 1, "prompt": "Khi thay thanh nhớ trong ảnh, em đang thay loại linh kiện nào?", "choices": ["RAM", "CPU", "SSD", "GPU"], "solution": "RAM", "explanation": "Thanh RAM có dãy chip nhớ và hàng chân tiếp xúc để gắn vào khe bộ nhớ.", "media": "m02", "mediaTitle": "Thanh bộ nhớ RAM"}
,{"id": "ap-1-cpu-locate", "concept": "cpu-locate", "lesson": 1, "prompt": "Chọn tên của linh kiện trong ảnh chụp mặt tiếp xúc này.", "choices": ["Bộ xử lý trung tâm", "Thanh RAM", "Ổ cứng cơ học", "Bo mạch chủ"], "solution": "Bộ xử lý trung tâm", "explanation": "Đây là mặt dưới của bộ xử lý, nơi tiếp xúc với ổ cắm trên bo mạch chủ.", "media": "m01", "mediaTitle": "Mặt tiếp xúc của CPU"}
,{"id": "ap-1-disk-arm", "concept": "disk-arm", "lesson": 1, "prompt": "Trên ổ lưu trữ đang mở trong ảnh, bộ phận ở đầu cánh tay di chuyển làm nhiệm vụ gì?", "choices": ["Đọc và ghi dữ liệu trên đĩa từ", "Làm mát bộ xử lý", "Cấp nguồn cho màn hình", "Lưu chương trình đang chạy trong RAM"], "solution": "Đọc và ghi dữ liệu trên đĩa từ", "explanation": "Đầu đọc ghi di chuyển đến vị trí cần truy cập trên bề mặt đĩa.", "media": "m04", "mediaTitle": "Đĩa từ và đầu đọc ghi của HDD"}
,{"id": "ap-1-saved-before-outage", "concept": "saved-before-outage", "lesson": 1, "prompt": "Em nhấn Lưu lúc 9 giờ, gõ thêm ba dòng rồi mất điện. Tự lưu đang tắt. Mở lại tệp thường thấy gì?", "choices": ["Nội dung đến lần lưu lúc 9 giờ", "Cả ba dòng vì RAM giữ dữ liệu sau mất điện", "Chỉ ba dòng mới gõ", "Tệp tự quay về bản đầu tiên trong ngày"], "solution": "Nội dung đến lần lưu lúc 9 giờ", "explanation": "Lần lưu đã ghi dữ liệu ra ổ. Phần thay đổi chỉ trong RAM có thể mất."}
,{"id": "ap-1-disk-not-memory", "concept": "disk-not-memory", "lesson": 1, "prompt": "Ổ lưu trữ báo đầy khi lưu video mới. Thao tác nào trực tiếp tạo thêm chỗ lưu?", "choices": ["Chuyển bớt tệp đã kiểm tra sang ổ khác rồi giải phóng dung lượng", "Đóng một cửa sổ rồi giữ nguyên các tệp", "Tăng xung nhịp CPU", "Khởi động lại mà giữ nguyên mọi tệp"], "solution": "Chuyển bớt tệp đã kiểm tra sang ổ khác rồi giải phóng dung lượng", "explanation": "Dung lượng chứa tệp khác với dung lượng bộ nhớ làm việc."}
,{"id": "ap-1-graphics-work", "concept": "graphics-work", "lesson": 1, "prompt": "Khi dựng một cảnh 3D, linh kiện nào chuyên thực hiện nhiều phép tính đồ họa?", "choices": ["GPU", "Ổ SSD", "Bộ nguồn", "Ổ HDD"], "solution": "GPU", "explanation": "GPU là bộ xử lý đồ họa."}
,{"id": "ap-2-keyboard-photo", "concept": "keyboard-photo", "lesson": 2, "prompt": "Trong ảnh, người dùng tác động lên bộ phận nào để nhập ký tự?", "choices": ["Các phím", "Bề mặt cảm ứng để trỏ", "Đầu đọc quang", "Con lăn cuộn"], "solution": "Các phím", "explanation": "Các phím tạo tín hiệu nhập tương ứng với ký tự hoặc lệnh.", "media": "m10", "mediaTitle": "Bàn phím"}
,{"id": "ap-2-display-output", "concept": "display-output", "lesson": 2, "prompt": "Nếu tháo riêng thiết bị trong ảnh khỏi máy bàn, khả năng nào mất trực tiếp?", "choices": ["Xem hình ảnh đang xuất ra thiết bị đó", "Gõ văn bản bằng bàn phím", "Đọc tệp trên ổ lưu trữ", "Thu âm bằng micrô"], "solution": "Xem hình ảnh đang xuất ra thiết bị đó", "explanation": "Màn hình là thiết bị xuất hình ảnh của máy tính.", "media": "m11", "mediaTitle": "Màn hình máy tính"}
,{"id": "ap-3-detach", "concept": "detachable-form", "lesson": 3, "prompt": "Máy trong ảnh có thể tháo rời bàn phím. Khi tháo bàn phím, cách nhập nào vẫn phù hợp với thiết bị này?", "choices": ["Chạm bàn phím ảo trên màn hình", "Gõ trên bàn phím đã tháo và ngắt kết nối", "Dùng màn hình như máy quét giấy", "Nhập chữ qua loa ngoài"], "solution": "Chạm bàn phím ảo trên màn hình", "explanation": "Màn hình cảm ứng cho phép nhập bằng bàn phím ảo khi sử dụng ở dạng máy tính bảng.", "media": "m15", "mediaTitle": "Máy tính xách tay dạng tháo bàn phím"}
,{"id": "skill-compare-capacity", "lesson": 1, "concept": "compare-capacity", "prompt": "Một máy có 8 GB RAM và ổ SSD 256 GB. Con số nào nên xem khi muốn lưu thêm ảnh sau mỗi buổi học?", "choices": ["Dung lượng còn trống trên SSD", "Dung lượng RAM đã lắp", "Dung lượng RAM ứng dụng đang dùng", "Dung lượng bộ nhớ đệm CPU"], "solution": "Dung lượng còn trống trên SSD", "explanation": "Ảnh đã lưu chiếm dung lượng ổ lưu trữ. Dung lượng còn trống mới cho biết có thể chép thêm bao nhiêu."}
,{"id": "skill-identify-board-sockets", "lesson": 1, "concept": "identify-board-sockets", "prompt": "Quan sát bo mạch chủ trong ảnh. Vì sao không thể chọn khe cắm linh kiện chỉ dựa vào màu sắc?", "choices": ["Cần đối chiếu loại khe và chuẩn linh kiện", "Khe dài nhất nhận được mọi linh kiện", "Các khe cùng màu luôn thay thế được nhau", "Màu khe thể hiện dung lượng lưu trữ"], "solution": "Cần đối chiếu loại khe và chuẩn linh kiện", "explanation": "Mỗi loại linh kiện có giao tiếp riêng. Màu không xác định đầy đủ tính tương thích.", "media": "m05", "mediaTitle": "Bo mạch chủ có nhiều loại khe cắm"}
,{"id": "skill-disk-storage-choice", "lesson": 1, "concept": "disk-storage-choice", "prompt": "Phòng máy có hai ổ trống cùng dung lượng. Muốn giảm rủi ro va chạm với bộ phận cơ học khi mang đi, nên ưu tiên đặc điểm nào?", "choices": ["Không có đầu đọc và đĩa quay", "Có tốc độ quay cao hơn", "Có nhiều đĩa từ hơn", "Có cánh tay đọc di chuyển nhanh hơn"], "solution": "Không có đầu đọc và đĩa quay", "explanation": "Ổ dùng chip nhớ không cần bộ phận cơ học chuyển động để đọc dữ liệu."}
,{"id": "skill-output-without-input", "lesson": 2, "concept": "output-without-input", "prompt": "Một máy chiếu hiển thị giao diện lên tường. Người học chạm tường nhưng con trỏ không di chuyển. Giải thích nào đúng?", "choices": ["Chỉ có đường xuất hình, chưa có bộ nhận thao tác chạm", "Mọi máy chiếu đều nhận chạm nếu bật loa", "Màn hình càng sáng thì càng nhạy chạm", "Phóng to hình sẽ tự bật cảm ứng"], "solution": "Chỉ có đường xuất hình, chưa có bộ nhận thao tác chạm", "explanation": "Chiếu hình không tự tạo đường nhập thao tác chạm về máy tính."}
,{"id": "skill-wrong-endpoint", "lesson": 2, "concept": "wrong-endpoint", "prompt": "Bản ghi thử đã có tiếng, nhưng khi phát trước lớp chỉ người đeo tai nghe nghe được. Nên chỉnh gì?", "choices": ["Chọn loa phòng làm thiết bị xuất", "Tăng độ nhạy của micrô", "Ghép lại máy quét", "Đổi nguồn thu thành webcam"], "solution": "Chọn loa phòng làm thiết bị xuất", "explanation": "Bản ghi đã có âm thanh. Vấn đề nằm ở nơi âm thanh được phát."}
,{"id": "skill-input-pair", "lesson": 2, "concept": "input-pair", "prompt": "Cặp thiết bị nào chỉ thu dữ liệu vào máy khi ghi một cuộc phỏng vấn?", "choices": ["Webcam và micrô", "Webcam và loa", "Màn hình và micrô", "Máy chiếu và loa"], "solution": "Webcam và micrô", "explanation": "Webcam thu hình, micrô thu tiếng. Cả hai đưa dữ liệu vào máy."}
,{"id": "skill-phone-tradeoff", "lesson": 3, "concept": "phone-tradeoff", "prompt": "Em có thể đọc bài trên điện thoại nhưng cần biên tập nhiều trang văn bản. Hạn chế nào ảnh hưởng trực tiếp nhất?", "choices": ["Màn hình nhỏ và ít không gian gõ", "Điện thoại không thể mở văn bản", "Điện thoại luôn cần cắm điện", "Điện thoại không có bộ xử lý"], "solution": "Màn hình nhỏ và ít không gian gõ", "explanation": "Kích thước màn hình và cách nhập ảnh hưởng sự thuận tiện khi biên tập dài."}
,{"id": "skill-portable-power", "lesson": 3, "concept": "portable-power", "prompt": "Trong chuyến đi không có ổ cắm, hai laptop đều chạy được phần mềm cần dùng. Yếu tố nào quyết định hơn cho buổi học dài?", "choices": ["Thời lượng pin thực tế", "Màu bàn phím", "Số cổng màn hình ngoài", "Độ cao chân đế"], "solution": "Thời lượng pin thực tế", "explanation": "Cần nguồn điện đủ lâu để hoàn thành công việc khi di chuyển."}
,{"id": "skill-desktop-service", "lesson": 3, "concept": "desktop-service", "prompt": "Một màn hình rời bị hỏng, thùng máy riêng vẫn chạy. Phương án nào tận dụng được thiết bị còn tốt?", "choices": ["Thử một màn hình tương thích khác với thùng máy", "Thay toàn bộ thùng máy vì màn hình hỏng", "Xóa ổ lưu trữ rồi bật lại màn hình", "Tháo RAM để sửa tấm nền"], "solution": "Thử một màn hình tương thích khác với thùng máy", "explanation": "Trong cấu hình máy bàn rời, màn hình có thể được thay độc lập với thùng máy."}
,{"id": "skill-formula-values", "lesson": 4, "concept": "formula-values", "prompt": "Ô tổng chứa số 150 do em gõ tay. Khi sửa một đơn giá, vì sao tổng vẫn là 150?", "choices": ["Ô tổng chưa dùng công thức tham chiếu dữ liệu", "Tệp phải có hình minh họa mới tính được", "Chỉ bản in mới cập nhật tổng", "Phải đổi phông chữ của cột giá"], "solution": "Ô tổng chưa dùng công thức tham chiếu dữ liệu", "explanation": "Số nhập tay không phụ thuộc vào các ô dữ liệu khác.", "media": "m19", "mediaTitle": "Trang tính trong LibreOffice Calc"}
,{"id": "skill-author-access", "lesson": 4, "concept": "author-access", "prompt": "Hai bạn cùng mở tài liệu trực tuyến nhưng một bạn chỉ đọc được. Chủ tệp cần kiểm tra gì?", "choices": ["Quyền chỉnh sửa của tài khoản đó", "Kích cỡ trang khi in", "Ứng dụng xem ảnh mặc định", "Kiểu chữ của tiêu đề"], "solution": "Quyền chỉnh sửa của tài khoản đó", "explanation": "Mở được tệp không đồng nghĩa với có quyền chỉnh sửa."}
,{"id": "skill-document-vs-slides", "lesson": 4, "concept": "document-vs-slides", "prompt": "Cần phát tài liệu ba trang có đoạn văn dài và tiêu đề phân cấp. Đặc điểm nào khiến trình soạn thảo phù hợp?", "choices": ["Văn bản tự chảy qua dòng và trang", "Mỗi trang phải chứa một hiệu ứng chuyển cảnh", "Mọi đoạn văn đều cần nằm trong ô tính", "Mỗi dòng phải được lưu thành ảnh riêng"], "solution": "Văn bản tự chảy qua dòng và trang", "explanation": "Trình soạn thảo hỗ trợ bố cục văn bản dài và cấu trúc tiêu đề.", "media": "m20", "mediaTitle": "Văn bản mở trong LibreOffice Writer"}
,{"id": "skill-driver-after-install", "lesson": 5, "concept": "driver-after-install", "prompt": "Máy in hoạt động trên máy A. Trên máy B vừa cài hệ điều hành, máy in xuất hiện là thiết bị chưa nhận dạng. Kiểm tra gì trước?", "choices": ["Trình điều khiển đúng mẫu và hệ điều hành", "Khổ giấy của tệp đang soạn", "Căn lề đoạn văn", "Số bản in lần trước"], "solution": "Trình điều khiển đúng mẫu và hệ điều hành", "explanation": "Trình điều khiển giúp hệ điều hành giao tiếp đúng với phần cứng."}
,{"id": "skill-os-vs-app", "lesson": 5, "concept": "os-vs-app", "prompt": "Em đóng trình duyệt nhưng vẫn mở được tệp từ màn hình nền. Thành phần nào vẫn đang điều phối máy?", "choices": ["Hệ điều hành", "Trang web vừa đóng", "Tệp đã tải trong trình duyệt", "Tiện ích đánh dấu trang"], "solution": "Hệ điều hành", "explanation": "Đóng một ứng dụng không làm hệ điều hành ngừng hoạt động."}
,{"id": "skill-app-version", "lesson": 5, "concept": "app-version", "prompt": "Nhà phát triển ghi ứng dụng cần phiên bản hệ điều hành mới hơn. Nguồn thông tin nào cần đối chiếu trên máy?", "choices": ["Mục thông tin phiên bản hệ điều hành", "Tên người tạo thư mục", "Ngày tạo tài liệu gần nhất", "Phiên bản của một tệp PDF"], "solution": "Mục thông tin phiên bản hệ điều hành", "explanation": "So sánh phiên bản hệ thống với yêu cầu giúp đánh giá khả năng tương thích."}
,{"id": "skill-window-close", "lesson": 6, "concept": "window-close", "prompt": "Em bấm đóng cửa sổ tài liệu và thấy hộp hỏi lưu. Muốn giữ phần vừa sửa, em chọn gì?", "choices": ["Lưu rồi đóng", "Bỏ thay đổi", "Đóng máy cưỡng bức", "Đăng xuất ngay không lưu"], "solution": "Lưu rồi đóng", "explanation": "Lưu ghi phần chỉnh sửa trước khi kết thúc cửa sổ tài liệu."}
,{"id": "skill-unexpected-admin", "lesson": 6, "concept": "unexpected-admin", "prompt": "Khi cài phần mềm trên máy trường, hệ thống hỏi mật khẩu quản trị viên. Em nên làm gì?", "choices": ["Dừng và nhờ người phụ trách nếu cần cài", "Dùng mật khẩu của bạn cùng lớp", "Đổi tên bộ cài để tránh yêu cầu", "Đăng nhập tài khoản bất kỳ rồi cài"], "solution": "Dừng và nhờ người phụ trách nếu cần cài", "explanation": "Cài đặt có thể cần quyền cao hơn tài khoản học sinh."}
,{"id": "skill-whose-session", "lesson": 6, "concept": "whose-session", "prompt": "Vừa ngồi xuống máy, em thấy tài liệu của bạn khác vẫn mở. Trước khi nộp bài cá nhân cần kiểm tra gì?", "choices": ["Phiên hiện tại có đúng tài khoản của em", "Độ sáng có giống máy nhà", "Hình nền có màu em thích", "Cỡ chữ có đủ lớn"], "solution": "Phiên hiện tại có đúng tài khoản của em", "explanation": "Nộp trong phiên người khác có thể gắn bài với sai danh tính."}
,{"id": "skill-restore-version", "lesson": 7, "concept": "restore-version", "prompt": "Tệp có v01, v02 và v03. Em muốn so sánh v02 với v03. Cách nào giữ được cả hai?", "choices": ["Mở từng bản riêng và so nội dung trước khi lưu", "Đổi ngay tên v03 trùng v02 rồi ghi đè", "Xóa ngay bản có dung lượng nhỏ hơn", "Lưu cả hai vào cùng một tên và chọn thay thế"], "solution": "Mở từng bản riêng và so nội dung trước khi lưu", "explanation": "Hậu tố phiên bản giúp nhận diện nhưng không thay cho kiểm tra nội dung."}
,{"id": "skill-copy-vs-move", "lesson": 7, "concept": "copy-vs-move", "prompt": "Sau khi chép một tệp từ USB sang máy lớp, em muốn cả hai nơi đều có tệp. Chọn thao tác nào?", "choices": ["Sao chép rồi dán", "Cắt rồi dán", "Đổi tên rồi di chuyển", "Chỉ tạo lối tắt đến USB"], "solution": "Sao chép rồi dán", "explanation": "Sao chép tạo bản ở đích và giữ tệp nguồn. Lối tắt vẫn phụ thuộc USB."}
,{"id": "skill-folder-scope", "lesson": 7, "concept": "folder-scope", "prompt": "Em tìm trong thư mục Toán mà không thấy bài Tin học. Bước hợp lý tiếp theo là gì?", "choices": ["Mở rộng phạm vi tìm sang thư mục môn Tin hoặc thư mục cha", "Định dạng lại ổ vì tệp chắc chắn đã mất", "Đổi tên mọi thư mục thành Toán", "Tạo lại tệp trước khi kiểm tra vị trí"], "solution": "Mở rộng phạm vi tìm sang thư mục môn Tin hoặc thư mục cha", "explanation": "Phạm vi tìm quá hẹp có thể bỏ qua tệp vẫn tồn tại ở thư mục khác."}
,{"id": "skill-pair-new", "lesson": 9, "concept": "pair-new", "prompt": "Tai nghe mới chưa có trong danh sách thiết bị đã ghép. Để máy tìm thấy tai nghe, em cần làm gì?", "choices": ["Bật Bluetooth và đưa tai nghe vào chế độ ghép nối", "Chỉ mở một website phát nhạc", "Chỉ đổi mật khẩu Wi-Fi", "Chuyển trình duyệt mặc định"], "solution": "Bật Bluetooth và đưa tai nghe vào chế độ ghép nối", "explanation": "Ghép nối yêu cầu liên kết Bluetooth và thiết bị có thể được phát hiện."}
,{"id": "skill-network-vs-internet", "lesson": 9, "concept": "network-vs-internet", "prompt": "Biểu tượng cho biết máy đã vào Wi-Fi lớp. Điều nào chưa thể khẳng định chỉ từ biểu tượng này?", "choices": ["Máy truy cập được Internet", "Máy đang có liên kết không dây với mạng", "Bộ Wi-Fi đang hoạt động để kết nối", "Máy đang sử dụng một mạng Wi-Fi"], "solution": "Máy truy cập được Internet", "explanation": "Liên kết tới điểm truy cập và đường từ mạng đó ra Internet là hai chặng khác nhau."}
,{"id": "skill-distance-test", "lesson": 9, "concept": "distance-test", "prompt": "Muốn kiểm tra tường có làm yếu Wi-Fi không, em so sánh cách nào?", "choices": ["Cùng máy, cùng mạng, đo gần điểm phát rồi đo sau tường", "Đổi cả máy và mạng ở lần thử sau", "So tốc độ Bluetooth với dung lượng pin", "Thử ở hai địa điểm bằng hai website khác nhau và hai mạng khác nhau"], "solution": "Cùng máy, cùng mạng, đo gần điểm phát rồi đo sau tường", "explanation": "Giữ các yếu tố khác giống nhau giúp đánh giá ảnh hưởng của vị trí."}
,{"id": "skill-bookmark-vs-download", "lesson": 11, "concept": "bookmark-vs-download", "prompt": "Em lưu dấu trang một bài đọc. Khi mất mạng và chưa tải bài xuống, vì sao có thể không đọc được?", "choices": ["Dấu trang lưu địa chỉ, không bảo đảm lưu nội dung", "Dấu trang tự đổi thành ảnh", "Tất cả dấu trang bị xóa khi mất mạng", "Dấu trang chỉ dùng được một lần"], "solution": "Dấu trang lưu địa chỉ, không bảo đảm lưu nội dung", "explanation": "Muốn đọc ngoại tuyến cần có bản nội dung lưu trên thiết bị."}
,{"id": "skill-forward-history", "lesson": 11, "concept": "forward-history", "prompt": "Trong cùng tab, em mở trang A rồi B, sau đó nhấn Quay lại. Nút nào đưa em tới B mà không gõ lại địa chỉ?", "choices": ["Tiến tới", "Trang chủ", "Dừng tải", "Thêm dấu trang"], "solution": "Tiến tới", "explanation": "Tiến tới đi theo lịch sử phía sau lần quay lại trong tab."}
,{"id": "skill-browser-address", "lesson": 11, "concept": "browser-address", "prompt": "Em biết chính xác địa chỉ trang lớp. Cách nào đưa em tới đúng địa chỉ trực tiếp nhất?", "choices": ["Nhập đầy đủ địa chỉ vào thanh địa chỉ", "Chỉ tìm tên trường rồi mở quảng cáo đầu tiên", "Đặt một dấu trang trống", "Gõ tên lớp vào ô tìm trên trang bất kỳ"], "solution": "Nhập đầy đủ địa chỉ vào thanh địa chỉ", "explanation": "Thanh địa chỉ cho phép mở trực tiếp URL đích.", "media": "m21", "mediaTitle": "Thanh địa chỉ và ô tìm kiếm trong Firefox"}
,{"id": "skill-ad-ranking", "lesson": 12, "concept": "ad-ranking", "prompt": "Hai kết quả đứng đầu, một kết quả có ghi quảng cáo. Điều này cho biết gì?", "choices": ["Vị trí quảng cáo có thể do trả phí", "Quảng cáo chắc chắn là nguồn khoa học tốt nhất", "Quảng cáo chắc chắn do trường xuất bản", "Tất cả kết quả bên dưới đều sai"], "solution": "Vị trí quảng cáo có thể do trả phí", "explanation": "Vị trí quảng cáo không chứng minh chất lượng hay tính phù hợp."}
,{"id": "skill-cross-check", "lesson": 12, "concept": "cross-check", "prompt": "Hai trang đưa số liệu khác nhau cho cùng đề tài. Trước khi dùng, làm gì?", "choices": ["So nguồn gốc, thời điểm và phạm vi của hai số liệu", "Chọn số lớn hơn vì dễ trình bày", "Dùng số xuất hiện bằng chữ lớn hơn", "Chọn trang nhiều hiệu ứng hơn"], "solution": "So nguồn gốc, thời điểm và phạm vi của hai số liệu", "explanation": "Các nguồn có thể đo khác thời gian hoặc phạm vi. Kiểm tra giúp giải thích chênh lệch."}
,{"id": "skill-search-intent", "lesson": 12, "concept": "search-intent", "prompt": "Muốn tìm hình ảnh để nhận dạng thiết bị thay vì bài viết dài. Có thể thu hẹp kết quả bằng cách nào?", "choices": ["Chọn loại kết quả hình ảnh", "Đổi mật khẩu tài khoản tìm kiếm", "Thêm tên của mọi thiết bị vào cùng truy vấn", "Tăng cỡ chữ bài viết"], "solution": "Chọn loại kết quả hình ảnh", "explanation": "Lọc theo loại nội dung giúp tập trung vào kết quả trực quan."}
,{"id": "skill-attribution-record", "lesson": 13, "concept": "attribution-record", "prompt": "Đang thu thập ảnh cho nhóm, nên lưu thông tin nào cùng từng ảnh để cuối buổi ghi nguồn?", "choices": ["Tác giả, trang gốc và giấy phép tương ứng", "Chỉ tên người gửi trong nhóm", "Chỉ kích thước tính bằng pixel", "Chỉ thời điểm tải xuống"], "solution": "Tác giả, trang gốc và giấy phép tương ứng", "explanation": "Giữ thông tin theo từng ảnh giúp truy lại nguồn và điều kiện sử dụng."}
,{"id": "skill-license-per-file", "lesson": 13, "concept": "license-per-file", "prompt": "Một album có nhiều ảnh và mỗi ảnh ghi giấy phép riêng. Khi dùng ảnh thứ ba, em kiểm tra gì?", "choices": ["Giấy phép ngay tại ảnh thứ ba", "Giấy phép của ảnh đầu tiên là đủ", "Mặc định mọi ảnh đều thuộc phạm vi công cộng", "Chỉ tên tài khoản đăng album"], "solution": "Giấy phép ngay tại ảnh thứ ba", "explanation": "Điều kiện áp dụng có thể khác giữa các tác phẩm trong cùng album."}
,{"id": "skill-changing-attribution", "lesson": 13, "concept": "changing-attribution", "prompt": "Bạn đề nghị ghi “Nguồn Internet” cho ảnh yêu cầu ghi công. Thiếu thông tin quan trọng nào?", "choices": ["Thông tin nhận diện tác giả và nguồn cụ thể", "Màu của trình duyệt", "Số máy phòng học", "Số người có trong ảnh"], "solution": "Thông tin nhận diện tác giả và nguồn cụ thể", "explanation": "“Internet” không cho người đọc truy ra tác phẩm hoặc người cần ghi công."}
,{"id": "skill-profile-combination", "lesson": 14, "concept": "profile-combination", "prompt": "Từng bài chỉ nhắc một chi tiết như tên lớp, giờ tan học hoặc địa điểm. Xem cả ba bài có rủi ro gì?", "choices": ["Các chi tiết có thể ghép thành thông tin nhận dạng và lịch trình", "Chỉ bài dài mới có rủi ro", "Các chi tiết tự xóa khi đăng ngày khác", "Người xem chỉ thấy được một chi tiết mỗi tuần"], "solution": "Các chi tiết có thể ghép thành thông tin nhận dạng và lịch trình", "explanation": "Dữ liệu rời rạc có thể kết hợp làm lộ nhiều hơn từng bài riêng lẻ."}
,{"id": "skill-account-history", "lesson": 14, "concept": "account-history", "prompt": "Một tài khoản dùng biệt danh nhưng đăng công khai nhiều tháng. Dấu vết nào vẫn góp phần hình thành danh tính trực tuyến?", "choices": ["Nội dung bài đăng và các tương tác", "Chỉ mã kiểu chữ trình duyệt", "Chỉ dung lượng ổ cứng máy cá nhân", "Chỉ thời lượng sạc pin"], "solution": "Nội dung bài đăng và các tương tác", "explanation": "Dấu vết trực tuyến còn gồm hành vi và nội dung, ngoài tên hiển thị."}
,{"id": "skill-private-preview", "lesson": 14, "concept": "private-preview", "prompt": "Trước khi đổi ảnh đại diện thành ảnh tập thể lớp, điều gì cần cân nhắc?", "choices": ["Ảnh đại diện có thể hiển thị cho người ngoài lớp", "Ảnh vuông luôn giới hạn người xem", "Tên tệp quyết định ai được xem", "Giảm số pixel tự động đặt ảnh ở chế độ riêng tư"], "solution": "Ảnh đại diện có thể hiển thị cho người ngoài lớp", "explanation": "Cần xem phạm vi hiển thị thực tế và cân nhắc người xuất hiện trong ảnh."}
,{"id": "skill-public-correction", "lesson": 15, "concept": "public-correction", "prompt": "Bạn ghi nhầm ngày kiểm tra trong nhóm. Phản hồi nào vừa sửa thông tin vừa tôn trọng bạn?", "choices": ["“Lịch cô gửi ghi thứ Năm. Mình kiểm tra lại cùng nhau nhé.”", "“Bạn lúc nào cũng sai.”", "“Mọi người bỏ qua tất cả lời bạn này.”", "“Mình đăng lại lỗi của bạn lên trang khác nhé.”"], "solution": "“Lịch cô gửi ghi thứ Năm. Mình kiểm tra lại cùng nhau nhé.”", "explanation": "Góp ý vào thông tin có thể kiểm tra, tránh công kích cá nhân."}
,{"id": "skill-tone-ambiguity", "lesson": 15, "concept": "tone-ambiguity", "prompt": "Một câu đùa bằng chữ khiến bạn hiểu lầm. Bước nào dễ giải quyết nhất?", "choices": ["Hỏi bạn đã hiểu thế nào rồi giải thích lịch sự", "Lặp lại câu đùa bằng chữ in hoa", "Kêu gọi cả lớp đánh giá bạn", "Chụp tin nhắn để trêu tiếp"], "solution": "Hỏi bạn đã hiểu thế nào rồi giải thích lịch sự", "explanation": "Văn bản thiếu nét mặt và giọng nói nên trao đổi làm rõ sẽ giảm hiểu nhầm."}
,{"id": "skill-credit-classmate", "lesson": 15, "concept": "credit-classmate", "prompt": "Sử dụng ý tưởng của bạn trong bài nhóm, cách nào thể hiện sự tôn trọng?", "choices": ["Ghi nhận phần đóng góp của bạn", "Ghi toàn bộ là ý tưởng của mình", "Bỏ tên bạn để bài ngắn hơn", "Đổi vài từ rồi nhận là tự nghĩ"], "solution": "Ghi nhận phần đóng góp của bạn", "explanation": "Ghi nhận người đóng góp giúp hợp tác công bằng."}
,{"id": "skill-blog-order", "lesson": 16, "concept": "blog-order", "prompt": "Nhật ký trực tuyến có bài mới hiển thị trước. Muốn kể lại tiến trình từ đầu, nên dựa vào gì?", "choices": ["Ngày đăng của từng bài", "Màu nền của từng bài", "Số lượt thích hiện tại", "Tên người bình luận cuối cùng"], "solution": "Ngày đăng của từng bài", "explanation": "Ngày đăng cho biết thứ tự thời gian của nhật ký."}
,{"id": "skill-forum-search", "lesson": 16, "concept": "forum-search", "prompt": "Em định hỏi cách nộp bài trên diễn đàn. Bước nào tránh tạo nhiều luồng trùng nhau?", "choices": ["Tìm chủ đề đã có về cách nộp bài", "Đăng cùng câu hỏi ở tất cả chuyên mục", "Chỉ đọc tên người điều hành", "Mở một tài khoản mới cho mỗi câu hỏi"], "solution": "Tìm chủ đề đã có về cách nộp bài", "explanation": "Tìm trước có thể thấy lời giải và giữ thảo luận tập trung."}
,{"id": "skill-reply-audience", "lesson": 16, "concept": "reply-audience", "prompt": "Trên trang câu lạc bộ, em bấm bình luận dưới bài đăng công khai. Ai có thể thấy câu trả lời?", "choices": ["Người có quyền xem bài và phần bình luận", "Chỉ người đăng nhập bằng máy của em", "Chỉ người được nhắc tên", "Chỉ người viết bài trong mọi trường hợp"], "solution": "Người có quyền xem bài và phần bình luận", "explanation": "Bình luận theo phạm vi của thảo luận, khác tin nhắn riêng."}
