,{"id": "skill-new-login", "lesson": 19, "concept": "new-login", "prompt": "Dịch vụ báo một phiên đăng nhập lạ mà em không thực hiện. Em nên làm gì?", "choices": ["Mở dịch vụ qua địa chỉ đã biết và kiểm tra phiên đăng nhập", "Gửi mật khẩu vào nhóm để nhờ kiểm tra", "Chỉ đổi ảnh đại diện", "Đăng công khai mã xác thực vừa nhận"], "solution": "Mở dịch vụ qua địa chỉ đã biết và kiểm tra phiên đăng nhập", "explanation": "Kiểm tra trong dịch vụ chính thức giúp nhận biết và xử lý phiên lạ."}
,{"id": "skill-pressure", "lesson": 20, "concept": "pressure", "prompt": "Tin nhắn yêu cầu quyết định trong hai phút nếu không sẽ mất tài khoản. Dấu hiệu nào cần cảnh giác?", "choices": ["Áp lực thời gian nhằm cản việc xác minh", "Việc dùng câu có đủ chủ ngữ", "Việc có chữ số trong tin nhắn", "Việc người gửi viết bằng tiếng Việt"], "solution": "Áp lực thời gian nhằm cản việc xác minh", "explanation": "Thúc ép làm người nhận dễ hành động trước khi kiểm tra."}
