,{"id": "skill-backup-independent", "lesson": 21, "concept": "backup-independent", "prompt": "Hai thư mục nằm cùng ổ lưu trữ. Nếu ổ đó hỏng, hai bản cùng mất. Đây là thiếu sót gì?", "choices": ["Bản sao chưa độc lập với thiết bị nguồn", "Tên thư mục quá ngắn", "Hai bản dùng cùng phông chữ", "Cả hai tệp đều có phần mở rộng"], "solution": "Bản sao chưa độc lập với thiết bị nguồn", "explanation": "Bản dự phòng phải chịu được sự cố của nơi lưu chính."}
,{"id": "skill-update-delay", "lesson": 21, "concept": "update-delay", "prompt": "Vì sao nên cài bản vá bảo mật đã được người phụ trách phê duyệt?", "choices": ["Để khắc phục các điểm yếu đã biết", "Để mọi tệp tự được sao lưu ngoại tuyến", "Để được cấp quyền quản trị vĩnh viễn", "Để tài khoản tự đổi mật khẩu mỗi lần mở máy"], "solution": "Để khắc phục các điểm yếu đã biết", "explanation": "Bản vá sửa lỗi cụ thể và giảm rủi ro từ các điểm yếu đó."}
,{"id": "skill-permission-scope", "lesson": 21, "concept": "permission-scope", "prompt": "Ứng dụng cần một ảnh để nộp bài, hệ thống cho chọn giữa một ảnh và toàn bộ thư viện. Chọn cách nào vừa đủ?", "choices": ["Chỉ cấp ảnh cần nộp", "Cấp cả thư viện và danh bạ", "Cấp quyền cho mọi ứng dụng khác", "Luôn cho chạy nền với quyền xem mọi ảnh"], "solution": "Chỉ cấp ảnh cần nộp", "explanation": "Giới hạn dữ liệu truy cập theo nhu cầu làm giảm tác động nếu có sự cố."}
,{"id": "skill-clear-cookie", "lesson": 22, "concept": "clear-cookie", "prompt": "Sau khi xóa cookie của một website, em có thể gặp hiện tượng nào?", "choices": ["Website yêu cầu đăng nhập lại", "Mọi tệp đã tải ở máy bị xóa", "Mật khẩu tài khoản trên máy chủ tự đổi", "Máy tự gỡ trình duyệt"], "solution": "Website yêu cầu đăng nhập lại", "explanation": "Xóa cookie phiên có thể làm mất dấu hiệu nhận biết phiên đăng nhập."}
,{"id": "skill-permission-revisit", "lesson": 22, "concept": "permission-revisit", "prompt": "Đã cấp quyền vị trí cho một ứng dụng và nay muốn đổi quyết định. Em tìm ở đâu?", "choices": ["Phần quản lý quyền của ứng dụng hoặc hệ thống", "Tên thư mục chứa ảnh", "Hộp thoại chọn máy in", "Trang đổi hình nền"], "solution": "Phần quản lý quyền của ứng dụng hoặc hệ thống", "explanation": "Quyền đã cấp có thể được xem lại trong cài đặt quyền."}
,{"id": "skill-location-before-photo", "lesson": 22, "concept": "location-before-photo", "prompt": "Muốn ảnh mới chụp không tự ghi vị trí, nên kiểm tra gì trước khi chụp?", "choices": ["Tùy chọn gắn vị trí hoặc quyền vị trí của camera", "Chỉ tên album sẽ chứa ảnh", "Chỉ màu khung hình", "Chỉ độ lớn âm thanh màn trập"], "solution": "Tùy chọn gắn vị trí hoặc quyền vị trí của camera", "explanation": "Ngăn camera ghi vị trí từ đầu giúp giảm dữ liệu đi kèm ảnh mới."}]
$catalog$::jsonb) as q(id text,lesson int,prompt text,choices text[],solution text,explanation text,concept text,media text,"mediaTitle" text) on conflict(id) do update set prompt=excluded.prompt,choices=excluded.choices,solution=excluded.solution,explanation=excluded.explanation,concept=excluded.concept,media=excluded.media,media_title=excluded.media_title;
insert into public.ic3_quiz_history(student_id,concept,last_seen)
select distinct pl.student_id,q.concept,now() from public.ic3_arcade_player pl
cross join lateral unnest(pl.seen) old_id join public.ic3_arcade_questions q on q.id=old_id
where q.concept is not null on conflict do nothing;

-- Both modes serialize draws by student, including draws from different tabs.
create function public.ic3_pick(sid uuid, school uuid, stage int, p_excluded text[], practice boolean)
returns jsonb language plpgsql security definer set search_path='' as $$
declare picked jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(sid::text,0));
 with pool as (
  select id,lesson,concept,prompt,choices,solution,explanation,media,media_title,0 as priority
  from public.ic3_arcade_questions where concept is not null and (lesson=stage or (not practice and lesson<stage))
  union all
  select s.id::text,s.lesson,coalesce(c.concept,nullif(trim(s.concept_key),''),'school-'||s.id::text),s.q,s.choices,s.solution,s.why,null,null,1
  from public.student_web_practice_questions s
  left join public.ic3_arcade_questions c on c.concept is not null and public.ic3_normalize(c.prompt)=public.ic3_normalize(s.q)
  where practice and s.school_id=school and s.published and s.lesson=stage and trim(s.why)<>''
   and cardinality(s.choices)=4 and s.solution=any(s.choices)
   and (select count(distinct public.ic3_normalize(v)) from unnest(s.choices) v where public.ic3_normalize(v)<>'')=4
 ), prompts as (
  select distinct on (public.ic3_normalize(prompt)) * from pool order by public.ic3_normalize(prompt),priority,id
 ), uniq as (
  select distinct on (concept) * from prompts order by concept,priority,id
 )
 select to_jsonb(u)-'priority' into picked from uniq u
 left join public.ic3_quiz_history h on h.student_id=sid and h.concept=u.concept
 where not (u.concept=any(p_excluded))
 order by coalesce(h.presentations,0),(u.lesson=stage) desc,random() limit 1;
 if picked is not null then
  insert into public.ic3_quiz_history(student_id,concept,last_seen) values(sid,picked->>'concept',clock_timestamp())
  on conflict(student_id,concept) do update set last_seen=excluded.last_seen,presentations=public.ic3_quiz_history.presentations+1;
 end if;
 return picked;
end $$;
revoke all on function public.ic3_pick(uuid,uuid,int,text[],boolean) from public,anon,authenticated;

create function public.ic3_practice_turn(p_session_token text,p_run uuid,p_lesson int,p_action text,p_turn uuid,p_choice text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare who jsonb:=public.qlpm_student_web_whoami(p_session_token);
 sid uuid:=(who->>'student_id')::uuid; school uuid:=(who->>'school_id')::uuid;
 r public.ic3_practice_run%rowtype; q jsonb; options jsonb;
begin
 if sid is null or p_run is null or p_turn is null or p_lesson not between 1 and 22 then raise exception 'Phiên luyện tập không hợp lệ';end if;
 delete from public.ic3_practice_run where student_id=sid and deadline<now()-interval '1 day';
 insert into public.ic3_practice_run(student_id,run,lesson) values(sid,p_run,p_lesson) on conflict do nothing;
 select * into strict r from public.ic3_practice_run where student_id=sid and run=p_run for update;
 if r.lesson<>p_lesson then raise exception 'Bài học đã thay đổi';end if;
 if p_action='next' then
  if r.turn is distinct from p_turn then
   if r.turn is not null and r.result is null then raise exception 'Câu hiện tại chưa kết thúc';end if;
   q:=public.ic3_pick(sid,school,r.lesson,r.seen,true);
   if q is null then return jsonb_build_object('done',true);end if;
   r.item:=q;r.turn:=p_turn;r.deadline:=clock_timestamp()+interval '30 seconds';r.result:=null;
   update public.ic3_practice_run set turn=r.turn,item=q,seen=array_append(r.seen,q->>'concept'),deadline=r.deadline,result=null where student_id=sid and run=p_run;
  end if;
  if r.result is not null then return r.result;end if;
  select jsonb_agg(v order by md5(r.turn::text||v)) into options from jsonb_array_elements_text(r.item->'choices') v;
  return jsonb_build_object('turn',r.turn,'prompt',r.item->>'prompt','media',r.item->>'media','choices',options,'deadline',r.deadline,'server_now',clock_timestamp());
 elsif p_action='answer' and r.turn=p_turn then
  if r.result is null then
   r.result:=jsonb_build_object('correct',coalesce(clock_timestamp()<r.deadline and p_choice=r.item->>'solution',false),'solution',r.item->>'solution','explanation',r.item->>'explanation','media_title',r.item->>'media_title','lesson',r.lesson);
   update public.ic3_practice_run set result=r.result where student_id=sid and run=p_run;
  end if;
  return r.result;
 end if;
 raise exception 'Lượt trả lời không hợp lệ';
end $$;
revoke all on function public.ic3_practice_turn(text,uuid,int,text,uuid,text) from public;
grant execute on function public.ic3_practice_turn(text,uuid,int,text,uuid,text) to anon,authenticated;
-- 22 map x 7 encounters = 154 server-controlled waves.
-- Preserve student scores, cleared maps, hero equipment, historical star ledgers and current wave.
-- Failure retries from wave 4 if the player had reached wave 5-7; no mass reset.
CREATE OR REPLACE FUNCTION public.ic3_arcade_turn(p_session_token text, p_action text DEFAULT 'status'::text, p_turn uuid DEFAULT NULL::uuid, p_choice text DEFAULT NULL::text, p_item integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 who jsonb:=public.qlpm_student_desktop_whoami(p_session_token);
 sid uuid:=(who->>'student_id')::uuid;
 school uuid:=(who->>'school_id')::uuid;
 pl public.ic3_arcade_player%rowtype;
 q public.ic3_arcade_questions%rowtype;
 picked jsonb; review jsonb; response jsonb; bonus int:=0; outcome text; feedback text; ordered jsonb; wallet jsonb;
begin
 if sid is null then raise exception 'Phiên học sinh đã hết hạn. Vui lòng đăng nhập lại.'; end if;
 insert into public.ic3_arcade_player(student_id) values(sid) on conflict do nothing;
 select * into strict pl from public.ic3_arcade_player where student_id=sid for update;
 -- Existing player progress is retained; newly initialized wave HP starts at this lesson's first encounter.
 if pl.wave_hp<1 then pl.wave_hp:=160+80*pl.wave+12*pl.stage; end if;
 if p_action='answer' and pl.turn is null and p_turn=pl.settled_turn then return pl.settled_result; end if;
 if p_action='redeem' then
   if p_turn is null then raise exception 'Thiếu mã lần đổi quà'; end if;
   perform id from public.students where id=sid for update;
   if not exists(select 1 from public.ic3_arcade_gifts where student_id=sid and request_id=p_turn) then
     if coalesce((select available from public.ic3_star_wallets where student_id=sid and school_id=school),0)<2 then raise exception 'Cần đủ 2 sao để đổi quà'; end if;
     insert into public.ic3_arcade_gifts(student_id,request_id) values(sid,p_turn);
     insert into public.student_records(school_id,student_id,record_type,title,points,record_date)
     values(school,sid,'reward','Săn Sao IC3 · đổi quà',-2,(now() at time zone 'Asia/Ho_Chi_Minh')::date);
   end if;
   outcome:='redeemed';
 elsif p_action='costume' then
   if p_item is null or p_item not between 0 and least(19,pl.cleared) then raise exception 'Trang phục chưa mở'; end if;
   pl.costume:=p_item;
 elsif p_action='gear' then
   if p_item is null or p_item not between 0 and least(5,pl.cleared/3) then raise exception 'Trang bị chưa mở'; end if;
   pl.gear:=p_item;
 elsif p_action='answer' and pl.turn is not null and p_turn=pl.turn then
   select * into strict q from public.ic3_arcade_questions where id=pl.question;
   feedback:=q.explanation;
   review:=jsonb_build_object('solution',q.solution,'lesson',q.lesson,'media_title',q.media_title);
   if clock_timestamp()<=pl.deadline and p_choice=q.solution then
     outcome:='correct';pl.score:=pl.score+10;pl.wave_hp:=greatest(0,pl.wave_hp-160-pl.gear*18);
     bonus:=case pl.score when 400 then 1 when 800 then 1 when 1600 then 2 when 4200 then 2 else 0 end;
     if bonus>0 then
       insert into public.student_records(school_id,student_id,record_type,title,points,note,record_date)
       values(school,sid,'reward','Săn Sao IC3 · '||pl.score||' điểm',bonus,'Thưởng mốc điểm trong một lượt sống',(now() at time zone 'Asia/Ho_Chi_Minh')::date);
     end if;
     if pl.wave_hp=0 then
       if pl.wave<7 then
         outcome:='wave_clear';
         pl.wave:=pl.wave+1;
         pl.wave_hp:=160+80*pl.wave+12*pl.stage;
         pl.hearts:=least(3,pl.hearts+1);
       else
         outcome:='victory';
         pl.cleared:=greatest(pl.cleared,pl.stage);
         pl.stage:=least(22,pl.stage+1);
         pl.wave:=1;
         pl.wave_hp:=160+80*pl.wave+12*pl.stage;
         pl.seen:='{}';
       end if;
     end if;
   else
     outcome:='wrong';pl.hearts:=greatest(0,pl.hearts-1);
     if pl.hearts=0 then outcome:='defeat';pl.hearts:=3;pl.score:=0;
        pl.wave:=case when pl.wave>=5 then 4 else 1 end;pl.wave_hp:=160+80*pl.wave+12*pl.stage;pl.seen:='{}';end if;
   end if;
   pl.turn:=null;pl.question:=null;pl.deadline:=null;
 elsif p_action='next' and pl.turn is null then
   picked:=public.ic3_pick(sid,school,pl.stage,pl.seen,false);
   if picked is null then
     -- A full bank has been seen. End the set without changing combat progress.
     outcome:='set_complete';pl.seen:='{}';
   else
     pl.seen:=array_append(pl.seen,picked->>'concept');pl.question:=picked->>'id';
     pl.turn:=gen_random_uuid();pl.deadline:=clock_timestamp()+interval '30 seconds';
   end if;
 elsif p_action not in ('status','answer','next') then raise exception 'Thao tác không hợp lệ';end if;
 update public.ic3_arcade_player set stage=pl.stage,cleared=pl.cleared,score=pl.score,hearts=pl.hearts,hp=pl.hp,costume=pl.costume,gear=pl.gear,wave=pl.wave,wave_hp=pl.wave_hp,question=pl.question,turn=pl.turn,deadline=pl.deadline,seen=pl.seen where student_id=sid;
 if pl.turn is not null then
   select * into strict q from public.ic3_arcade_questions where id=pl.question;
   select jsonb_agg(v order by md5(pl.turn::text||v)) into ordered from unnest(q.choices) v;
 end if;
 select jsonb_build_object('earned',earned,'available',available) into wallet from public.ic3_star_wallets where student_id=sid and school_id=school;
 response:=(to_jsonb(pl)-'student_id'-'seen'-'question'-'settled_turn'-'settled_result')||jsonb_build_object('hp',pl.wave_hp,'wave',pl.wave,'wave_max_hp',160+80*pl.wave+12*pl.stage,'total_waves',7,'damage',160+18*pl.gear,'prompt',case when pl.turn is not null then q.prompt end,'choices',ordered,'outcome',outcome,'media',case when pl.turn is not null then q.media end,'review',review,'feedback',feedback,'bonus',bonus,'wallet',coalesce(wallet,'{"earned":0,"available":0}'::jsonb),'server_now',clock_timestamp());
 if review is not null then
   update public.ic3_arcade_player set settled_turn=p_turn,settled_result=response where student_id=sid;
 end if;
 return response;
end $function$
;
